#include <stdint.h>

void vectorized_s1113(float* a, float* b, float* out, int n)
{
    float scalar_val = a[n/2];
    int i = 0;
    int limit = n - (n % 8);
    for (; i < limit; i += 8) {
        out[i+0] = scalar_val + b[i+0];
        out[i+1] = scalar_val + b[i+1];
        out[i+2] = scalar_val + b[i+2];
        out[i+3] = scalar_val + b[i+3];
        out[i+4] = scalar_val + b[i+4];
        out[i+5] = scalar_val + b[i+5];
        out[i+6] = scalar_val + b[i+6];
        out[i+7] = scalar_val + b[i+7];
    }
    for (; i < n; i++) {
        out[i] = scalar_val + b[i];
    }
}

void s1113_opt(int iterations, int LEN_1D, float* a, float* b)
{
    int mid = LEN_1D / 2;
    for (int nl = 0; nl < 2 * iterations; nl++) {
        // Phase 1: i = 0 to mid-1, a[mid] not yet updated
        float mid_val = a[mid];
        for (int i = 0; i < mid; i++) {
            a[i] = mid_val + b[i];
        }
        // Mid-point update
        a[mid] = mid_val + b[mid];
        // Phase 2: i = mid+1 to LEN_1D-1, use updated a[mid]
        float new_mid_val = a[mid];
        for (int i = mid + 1; i < LEN_1D; i++) {
            a[i] = new_mid_val + b[i];
        }
    }
}
